enum class ThemeMode { SYSTEM, LIGHT, DARK }
private const val PreferencesName = "material_you_preferences"
private const val ThemeModeKey = "theme_mode"
private const val DynamicColorKey = "dynamic_color"
private const val LanguageKey = "language"

class MainActivity : ComponentActivity() { override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { MaterialYouApp() } } }

@Composable private fun MaterialYouApp() {
    val context = LocalContext.current
    val preferences = remember(context) { context.getSharedPreferences(PreferencesName, Context.MODE_PRIVATE) }
    var themeMode by rememberSaveable { mutableStateOf(ThemeMode.entries.firstOrNull { it.name == preferences.getString(ThemeModeKey, ThemeMode.SYSTEM.name) } ?: ThemeMode.SYSTEM) }
    var useDynamicColor by rememberSaveable { mutableStateOf(preferences.getBoolean(DynamicColorKey, true)) }
    var languageChoice by rememberSaveable { mutableStateOf(preferences.getString(LanguageKey, "auto") ?: "auto") }
    @Suppress("DEPRECATION") val deviceLanguage = LocalConfiguration.current.locale.language.lowercase().let { if (it == "pt" || it == "es") it else "en" }
    val appLanguage = if (languageChoice == "auto") deviceLanguage else languageChoice
    CompositionLocalProvider(LocalAppLanguage provides appLanguage) { MaterialYouTheme(themeMode, useDynamicColor) {
        StarterScreen(themeMode, { themeMode = it; preferences.edit().putString(ThemeModeKey, it.name).apply() }, useDynamicColor, { useDynamicColor = it; preferences.edit().putBoolean(DynamicColorKey, it).apply() }, languageChoice, { languageChoice = it; preferences.edit().putString(LanguageKey, it).apply() })
    } }
}
@Composable private fun MaterialYouTheme(themeMode: ThemeMode, useDynamicColor: Boolean, content: @Composable () -> Unit) {
    val dark = when (themeMode) { ThemeMode.SYSTEM -> isSystemInDarkTheme(); ThemeMode.LIGHT -> false; ThemeMode.DARK -> true }
    val context = LocalContext.current
    val colors = when { useDynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> if (dark) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context); dark -> GreenDarkScheme; else -> GreenLightScheme }
    MaterialTheme(colorScheme = colors, content = content)
}
