private val GreenDarkScheme = darkColorScheme(primary = androidx.compose.ui.graphics.Color(0xFF9BD9AA), onPrimary = androidx.compose.ui.graphics.Color(0xFF00391D), primaryContainer = androidx.compose.ui.graphics.Color(0xFF07522E), onPrimaryContainer = androidx.compose.ui.graphics.Color(0xFFB7F6CA), secondary = androidx.compose.ui.graphics.Color(0xFFB4CCB9), onSecondary = androidx.compose.ui.graphics.Color(0xFF203529), secondaryContainer = androidx.compose.ui.graphics.Color(0xFF364B3C), onSecondaryContainer = androidx.compose.ui.graphics.Color(0xFFD0E8D4), tertiary = androidx.compose.ui.graphics.Color(0xFFA2CEDC), onTertiary = androidx.compose.ui.graphics.Color(0xFF043640), tertiaryContainer = androidx.compose.ui.graphics.Color(0xFF214C57), onTertiaryContainer = androidx.compose.ui.graphics.Color(0xFFBEEAF8), background = androidx.compose.ui.graphics.Color(0xFF111411), onBackground = androidx.compose.ui.graphics.Color(0xFFE1E4DD), surface = androidx.compose.ui.graphics.Color(0xFF111411), onSurface = androidx.compose.ui.graphics.Color(0xFFE1E4DD), surfaceVariant = androidx.compose.ui.graphics.Color(0xFF404941), onSurfaceVariant = androidx.compose.ui.graphics.Color(0xFFC0C9C0), outline = androidx.compose.ui.graphics.Color(0xFF8A938A))

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun StarterScreen(themeMode: ThemeMode, onThemeModeChange: (ThemeMode) -> Unit, useDynamicColor: Boolean, onDynamicColorChange: (Boolean) -> Unit, languageChoice: String, onLanguageChange: (String) -> Unit) {
    var destination by rememberSaveable { mutableIntStateOf(0) }; var filter by rememberSaveable { mutableStateOf("Todos") }; var notifications by rememberSaveable { mutableStateOf(true) }; var intensity by rememberSaveable { mutableFloatStateOf(.64f) }; var dialog by rememberSaveable { mutableStateOf(false) }
    val snack = remember { SnackbarHostState() }; val scope = rememberCoroutineScope(); val destinations = listOf(Destination("Explorar", Icons.Outlined.AutoAwesome), Destination("Tema", Icons.Outlined.Palette), Destination("Sobre", Icons.Outlined.Code))
    Scaffold(topBar = { TopAppBar(title = { T("Material You") }, actions = { IconButton(onClick = { onThemeModeChange(if (themeMode == ThemeMode.DARK) ThemeMode.LIGHT else ThemeMode.DARK) }) { Icon(if (themeMode == ThemeMode.DARK) Icons.Outlined.LightMode else Icons.Outlined.DarkMode, localized("Alternar tema", LocalAppLanguage.current)) } }) }, snackbarHost = { SnackbarHost(snack) }, bottomBar = { NavigationBar { destinations.forEachIndexed { i, item -> NavigationBarItem(destination == i, { destination = i }, { Icon(item.icon, null) }, label = { T(item.label) }) } } }, floatingActionButton = { ExtendedFloatingActionButton(onClick = { dialog = true }, icon = { Icon(Icons.Outlined.AutoAwesome, null) }, text = { T("Ver diálogo") }) }) { padding -> when (destination) { 0 -> ExplorePage(padding, filter, { filter = it }, notifications, { notifications = it }, intensity, { intensity = it }) { scope.launch { snack.showSnackbar(localized("Ação de exemplo concluída", LocalAppLanguage.current)) } }; 1 -> ThemePage(padding, themeMode, onThemeModeChange, useDynamicColor, onDynamicColorChange, languageChoice, onLanguageChange); else -> AboutPage(padding) } }
    if (dialog) AlertDialog(onDismissRequest = { dialog = false }, title = { T("Um diálogo Material 3") }, text = { T("Use diálogos para escolhas importantes e mantenha o conteúdo direto.") }, confirmButton = { TextButton(onClick = { dialog = false }) { T("Entendi") } }, dismissButton = { TextButton(onClick = { dialog = false }) { T("Fechar") } })
}
private data class Destination(val label: String, val icon: ImageVector)
@Composable private fun ExplorePage(padding: PaddingValues, filter: String, onFilter: (String) -> Unit, notifications: Boolean, onNotifications: (Boolean) -> Unit, intensity: Float, onIntensity: (Float) -> Unit, onAction: () -> Unit) {
    var pressed by remember { mutableStateOf(false) }; val scope = rememberCoroutineScope(); val scale by animateFloatAsState(if (pressed) .965f else 1f, spring(dampingRatio = .58f, stiffness = 420f), label = "example-card-spring")
    LazyColumn(Modifier.fillMaxSize().padding(padding), contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) { item { T("MATERIAL 3 • COMPOSE", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp)); T("Uma base nativa, clara e pronta para adaptar.", style = MaterialTheme.typography.headlineMedium); Spacer(Modifier.height(8.dp)); T("Experimente preferências persistentes, Dynamic Color e uma paleta verde de fallback.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer), modifier = Modifier.graphicsLayer { scaleX = scale; scaleY = scale }.clickable { scope.launch { pressed = true; delay(110); pressed = false } }) { Column(Modifier.fillMaxWidth().padding(24.dp)) { T("Feito para o sistema", style = MaterialTheme.typography.titleLarge, color = MaterialTheme.colorScheme.onPrimaryContainer); Spacer(Modifier.height(8.dp)); T("No Android 12+, a cor dinâmica pode seguir o papel de parede. Em outras versões, os papéis semânticos continuam consistentes.", color = MaterialTheme.colorScheme.onPrimaryContainer); Spacer(Modifier.height(14.dp)); Button(onClick = onAction) { T("Testar ação") } } } }; item { T("Filtros", style = MaterialTheme.typography.titleLarge) }; item { Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { listOf("Todos", "Design", "Android").forEach { FilterChip(filter == it, { onFilter(it) }, label = { T(it) }) } } }; item { Card { Column(Modifier.fillMaxWidth().padding(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) { Column(Modifier.weight(1f)) { T("Notificações", style = MaterialTheme.typography.titleMedium); T("Exemplo de preferência de interface", color = MaterialTheme.colorScheme.onSurfaceVariant, style = MaterialTheme.typography.bodySmall) }; Spacer(Modifier.width(12.dp)); Switch(notifications, onNotifications) }; Text("${localized("Intensidade", LocalAppLanguage.current)} · ${(intensity * 100).toInt()}%", style = MaterialTheme.typography.titleMedium); Slider(intensity, onIntensity) } } }; item { Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.tertiaryContainer)) { ListItem(headlineContent = { T("Papéis semânticos") }, supportingContent = { T("Use primary, containers e superfícies no lugar de cores soltas.") }, leadingContent = { Icon(Icons.Outlined.SettingsSuggest, null) }, colors = ListItemDefaults.colors(containerColor = MaterialTheme.colorScheme.tertiaryContainer)) } } }
}
@Composable private fun ThemePage(padding: PaddingValues, themeMode: ThemeMode, onTheme: (ThemeMode) -> Unit, dynamic: Boolean, onDynamic: (Boolean) -> Unit, choice: String, onLanguage: (String) -> Unit) { val available = Build.VERSION.SDK_INT >= Build.VERSION_CODES.S; var expanded by remember { mutableStateOf(false) }; LazyColumn(Modifier.fillMaxSize().padding(padding), contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) { item { T("Personalize", style = MaterialTheme.typography.headlineMedium); Spacer(Modifier.height(8.dp)); T("As preferências abaixo são salvas no aparelho e sobrevivem ao reinício do app.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card { Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { T("Tema", style = MaterialTheme.typography.titleLarge); ThemeMode.entries.forEach { mode -> FilterChip(themeMode == mode, { onTheme(mode) }, label = { T(when(mode) { ThemeMode.SYSTEM -> "Sistema"; ThemeMode.LIGHT -> "Claro"; ThemeMode.DARK -> "Escuro" }) }) } } } }; item { Card { Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { T("Idioma do app", style = MaterialTheme.typography.titleLarge); Box { OutlinedButton(onClick = { expanded = true }) { T(languageLabel(choice)) }; DropdownMenu(expanded, { expanded = false }) { listOf("auto" to "Automático (sistema)", "pt" to "Português", "en" to "English", "es" to "Español").forEach { (value, label) -> DropdownMenuItem(text = { T(label) }, onClick = { onLanguage(value); expanded = false }) } } }; T("Automático usa o idioma preferido do aparelho; a escolha manual fica salva neste app.", color = MaterialTheme.colorScheme.onSurfaceVariant) } } }; item { Card { ListItem(headlineContent = { T("Cor dinâmica") }, supportingContent = { T(if (available) "Usa as cores do sistema no Android 12 ou superior." else "Indisponível neste Android; a paleta verde de fallback está em uso.") }, trailingContent = { Switch(dynamic, onDynamic, enabled = available) }) } }; item { Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)) { Column(Modifier.padding(20.dp)) { T("Fallback verde", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSecondaryContainer); Spacer(Modifier.height(8.dp)); T("Uma paleta clara e uma escura estão definidas para dispositivos antigos ou quando a cor dinâmica é desligada.", color = MaterialTheme.colorScheme.onSecondaryContainer) } } } } }
private fun languageLabel(choice: String) = when(choice) { "pt" -> "Português"; "en" -> "English"; "es" -> "Español"; else -> "Automático (sistema)" }
@Composable private fun AboutPage(padding: PaddingValues) { LazyColumn(Modifier.fillMaxSize().padding(padding), contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) { item { T("Comece pelo seu projeto", style = MaterialTheme.typography.headlineMedium) }; item { T("Esta demonstração usa Material 3 estável, Compose e cores semânticas. Copie a estrutura, não apenas os pixels.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card { ListItem(headlineContent = { T("1. Escolha um tema") }, supportingContent = { T("Sistema, claro ou escuro, sempre com fallback consistente.") }, leadingContent = { Icon(Icons.Outlined.Palette, null) }) } }; item { Card { ListItem(headlineContent = { T("2. Revise acessibilidade") }, supportingContent = { T("Valide contraste, foco, toque e leitor de tela no produto final.") }, leadingContent = { Icon(Icons.Outlined.AutoAwesome, null) }) } } } }